package pl.dmq.peering.platform.net

import java.io.File
import java.security.KeyStore
import java.security.PrivateKey
import java.security.cert.X509Certificate
import java.security.interfaces.ECPublicKey
import pl.dmq.peering.platform.identity.uncompressedPoint

/**
 * A self signed P-256 certificate for tests. Generated by the JDK's `keytool`, run as a child process, because the
 * JDK's internal `sun.security.x509` builder is not exported to code compiled outside java.base.
 */
class PeerCredentials private constructor(
    private val chain: List<X509Certificate>,
    private val key: PrivateKey,
) : TlsCredentials {
    /** The 65-byte point of the leaf, as the trust manager reports it. */
    val point: ByteArray get() = uncompressedPoint(chain.first().publicKey as ECPublicKey)

    override fun certificateChain(): List<X509Certificate> = chain

    override fun privateKey(): PrivateKey = key

    companion object {
        const val ALIAS = "peer"
        const val PASSWORD = "changeit"

        fun generate(directory: File, name: String): PeerCredentials {
            val keystore = File(directory, "$name.p12")
            val keytool = File(System.getProperty("java.home"), "bin/keytool").path
            val process = ProcessBuilder(
                keytool, "-genkeypair", "-alias", ALIAS, "-keyalg", "EC", "-groupname", "secp256r1",
                "-sigalg", "SHA256withECDSA", "-dname", "CN=$name, O=Peering", "-validity", "3650",
                "-storetype", "PKCS12", "-keystore", keystore.path, "-storepass", PASSWORD, "-keypass", PASSWORD,
            ).redirectErrorStream(true).start()
            val output = process.inputStream.bufferedReader().readText()
            check(process.waitFor() == 0) { "keytool failed: $output" }
            return load(keystore)
        }

        fun load(keystore: File): PeerCredentials {
            val store = KeyStore.getInstance("PKCS12")
            keystore.inputStream().use { store.load(it, PASSWORD.toCharArray()) }
            val chain = store.getCertificateChain(ALIAS).map { it as X509Certificate }
            val key = store.getKey(ALIAS, PASSWORD.toCharArray()) as PrivateKey
            return PeerCredentials(chain, key)
        }
    }
}
